/**
 * 按题目 id 找题（批改页 ?id= 预填用）
 * @param {string} id 题目 id
 * @returns {object|null} 命中返回 {paper, question, index}
 */
function getQuestionById(id) {
  if (!id) return null;
  var key = String(id);
  for (var i = 0; i < PAPERS.length; i++) {
    var qs = PAPERS[i].questions || [];
    for (var j = 0; j < qs.length; j++) {
      if (qs[j].id === key) {
        return { paper: PAPERS[i], question: qs[j], index: j };
      }
    }
  }
  return null;
}

